-- 567: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 14 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_567_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_567_guard;
INSERT INTO _migration_567_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_053' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_env' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The local Ghanaian term for illegal small-scale gold mining is...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Galamsey","B. Quarrying","C. Surface mining","D. Sand winning"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Galamsey — a corruption of “gather them and sell” — denotes unlicensed gold mining that evades regulation, unlike registered small-scale mining, which is legal. Quarrying extracts stone, surface mining is a legitimate licensed technique, and sand winning removes sand for construction. Therefore the correct answer is A: Galamsey.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_053' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_567_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_054' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_env' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a direct environmental effect of galamsey operations in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increased fish stocks in the rivers","B. Pollution of rivers such as the Pra and Ankobra with silt and mercury","C. Improved fertility of cocoa farmland","D. Expansion of forest cover in mining areas"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Galamsey washes soil and mercury into rivers such as the Pra, Ankobra and Birim, making water turbid, costly to treat and poisonous to fish and people. Fish stocks fall, farmland is excavated and degraded, and forest is cleared — the exact opposite of the three distractors. Therefore the correct answer is B: Pollution of rivers such as the Pra and Ankobra with silt and mercury.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_054' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_567_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_055' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_env' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The clearing of forests without replanting, leading to permanent loss of tree cover, is called...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Afforestation","B. Reforestation","C. Deforestation","D. Desertification"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Deforestation is the removal of forest without replacement. Afforestation is planting trees where none existed, reforestation is replanting cleared forest, and desertification is the degradation of dry land into desert — a possible result of deforestation, not the clearing itself. Therefore the correct answer is C: Deforestation.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_055' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_567_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_056' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_env' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a renewable natural resource in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Gold deposits","B. Crude oil reserves","C. Bauxite ore","D. Forest timber, when trees are replanted"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Renewable resources regenerate within a human timescale: forests regrow if harvested sustainably and replanted, as do fisheries and solar energy. Gold, crude oil and bauxite are minerals that take millions of years to form, so once mined they are gone — non-renewable resources. Therefore the correct answer is D: Forest timber, when trees are replanted.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_056' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_053', 'topic_wassce_p2_soc_env', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'The local Ghanaian term for illegal small-scale gold mining is...', 'multiple_choice', NULL, '["A. Galamsey","B. Quarrying","C. Surface mining","D. Sand winning"]', 'A', 'Galamsey — a corruption of “gather them and sell” — denotes unlicensed gold mining that evades regulation, unlike registered small-scale mining, which is legal. Quarrying extracts stone, surface mining is a legitimate licensed technique, and sand winning removes sand for construction. Therefore the correct answer is A: Galamsey.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_054', 'topic_wassce_p2_soc_env', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a direct environmental effect of galamsey operations in Ghana?', 'multiple_choice', NULL, '["A. Increased fish stocks in the rivers","B. Pollution of rivers such as the Pra and Ankobra with silt and mercury","C. Improved fertility of cocoa farmland","D. Expansion of forest cover in mining areas"]', 'B', 'Galamsey washes soil and mercury into rivers such as the Pra, Ankobra and Birim, making water turbid, costly to treat and poisonous to fish and people. Fish stocks fall, farmland is excavated and degraded, and forest is cleared — the exact opposite of the three distractors. Therefore the correct answer is B: Pollution of rivers such as the Pra and Ankobra with silt and mercury.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_055', 'topic_wassce_p2_soc_env', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'The clearing of forests without replanting, leading to permanent loss of tree cover, is called...', 'multiple_choice', NULL, '["A. Afforestation","B. Reforestation","C. Deforestation","D. Desertification"]', 'C', 'Deforestation is the removal of forest without replacement. Afforestation is planting trees where none existed, reforestation is replanting cleared forest, and desertification is the degradation of dry land into desert — a possible result of deforestation, not the clearing itself. Therefore the correct answer is C: Deforestation.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_056', 'topic_wassce_p2_soc_env', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a renewable natural resource in Ghana?', 'multiple_choice', NULL, '["A. Gold deposits","B. Crude oil reserves","C. Bauxite ore","D. Forest timber, when trees are replanted"]', 'D', 'Renewable resources regenerate within a human timescale: forests regrow if harvested sustainably and replanted, as do fisheries and solar energy. Gold, crude oil and bauxite are minerals that take millions of years to form, so once mined they are gone — non-renewable resources. Therefore the correct answer is D: Forest timber, when trees are replanted.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-social-studies-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_was_soc_s3_053', 'q_was_soc_s3_054', 'q_was_soc_s3_055', 'q_was_soc_s3_056');
